findings.codeql_raw_query:
/**
 * @name Format string injection from user input
 * @description Format operations with user-controlled format strings can lead to information disclosure
 * @kind path-problem
 * @problem.severity warning
 * @id py/click-taint-format-injection
 * @tags security
 *        external/cwe/cwe-134
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module FormatInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // User input from command line arguments, parameters, etc.
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("click").getMember(["prompt", "confirm", "get_text_stream"]).getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // Format string operations where the format string itself is tainted
    exists(DataFlow::CallCfgNode call |
      call.getFunction().asCfgNode().(AttrNode).getObject("format") = sink.asCfgNode()
    )
  }
}

module FormatInjectionFlow = TaintTracking::Global<FormatInjectionConfig>;
import FormatInjectionFlow::PathGraph

from FormatInjectionFlow::PathNode source, FormatInjectionFlow::PathNode sink
where FormatInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Format string may be controlled by user input from $@.", source.getNode(), "here"
